de":"aria:parking-scan"},{"from":"PARKING_OUT_1","to":"WEIGHMENT_1","trigger":"page.submitted","pageCode":"aria:weighment-capture"},{"from":"WEIGHMENT_1","to":"LOADING_IN_PROGRESS","trigger":"page.submitted","pageCode":"aria:loading-in-progress"},{"from":"LOADING_IN_PROGRESS","to":"QC_SAMPLE_APPROVED","trigger":"page.submitted","pageCode":"aria:qc-final-out","guard":"#submitted[''status''] == ''APPROVED''"},{"from":"LOADING_IN_PROGRESS","to":"QC_SAMPLE_REJECTED","trigger":"page.submitted","pageCode":"aria:qc-final-out","guard":"#submitted[''status''] == ''REJECTED''"},{"from":"QC_SAMPLE_APPROVED","to":"WEIGHMENT_2","trigger":"page.submitted","pageCode":"aria:weighment-capture"},{"from":"WEIGHMENT_2","to":"PARKING_IN_2","trigger":"page.submitted","pageCode":"aria:parking-scan"},{"from":"PARKING_IN_2","to":"WEIGHT_DIFF_OK","trigger":"page.submitted","pageCode":"aria:weight-diff-entry","guard":"#submitted[''withinTolerance''] == ''YES''"},{"from":"PARKING_IN_2","to":"WEIGHT_DIFF_PENDING_MANAGER","trigger":"page.submitted","pageCode":"aria:weight-diff-entry","guard":"#submitted[''withinTolerance''] == ''NO''"},{"from":"WEIGHT_DIFF_PENDING_MANAGER","to":"WEIGHT_DIFF_OK","trigger":"page.submitted","pageCode":"aria:manager-qty-approval","guard":"#submitted[''status''] == ''APPROVED''"},{"from":"WEIGHT_DIFF_PENDING_MANAGER","to":"REJECTED_BY_MANAGER","trigger":"page.submitted","pageCode":"aria:manager-qty-approval","guard":"#submitted[''status''] == ''REJECTED''"},{"from":"WEIGHT_DIFF_OK","to":"BILLING_DONE","trigger":"page.submitted","pageCode":"aria:billing-entry"},{"from":"BILLING_DONE","to":"PARKING_OUT_2","trigger":"page.submitted","pageCode":"aria:parking-scan"},{"from":"PARKING_OUT_2","to":"WEIGHMENT_3","trigger":"page.submitted","pageCode":"aria:weighment-capture"},{"from":"WEIGHMENT_3","to":"READY_FOR_EXIT","trigger":"page.submitted","pageCode":"aria:manager-weight-approval","guard":"#submitted[''status''] == ''APPROVED''"},{"from":"WEIGHMENT_3","to":"REJECTED_BY_MANAGER","trigger":"page.submitted","pageCode":"aria:manager-weight-approval","guard":"#submitted[''status''] == ''REJECTED''"},{"from":"READY_FOR_EXIT","to":"GATE_PASS_OUT_CLOSED","trigger":"page.submitted","pageCode":"aria:gate-pass-closure-form","guard":"(#submitted[''weighment_verified''] == ''OK'' || #submitted[''weighment_verified''] == ''MGR_APPROVED'') && (#submitted[''seal_verified''] == ''MATCHED'' || #submitted[''seal_verified''] == ''NA'') && #submitted[''invoice_count_verified''] == ''YES''"}]}'
 WHERE code = 'M10.TankerOutbound' AND status = 'PUBLISHED';
